 keys=sorted(keys);ts=[round(k[0]*60) for k in keys];boxes=np.array([k[1:] for k in keys],float)
 first=round(begin*60);stop=round(end*60)
 for f in range(first,stop):
  b=[np.interp(f,ts,boxes[:,i]) for i in range(4)]
  x1=max(0,math.floor(b[0]-pad));y1=max(0,math.floor(b[1]-pad));x2=min(804,math.ceil(b[2]+pad));y2=min(452,math.ceil(b[3]+pad))
  if x2>x1 and y2>y1:frames.setdefault(str(f),[]).append([x1+ox,y1+oy,x2+ox,y2+oy])
 targets.append({'id':name,'panel':panel,'start_frame':first,'end_frame_exclusive':stop,'margin_px':pad,'keyframes_local_xyxy':keys})
